def forward(self, x):
    weights = torch.softmax(self.router(x), dim=-1)
    selected, indices = torch.topk(weights, 1, dim=-1)
    if indices.sum() > 0:
        y = self.b(x)
    else:
        y = self.a(x)
    return y * selected

